$wc = new WasteCompany($pdo);
$wc->ensureTable();

$existing = (int)$pdo->query("SELECT COUNT(*) FROM waste_companies")->fetchColumn();
if ($existing > 0 && empty($_GET['fresh'])) {
    exit("이미 {$existing}건 적재됨. 재적재하려면 &fresh=1 추가.");
}
if (!empty($_GET['fresh'])) { $wc->truncate(); }

$n = $wc->insertMany($ROWS);

// 검증
$total  = (int)$pdo->query("SELECT COUNT(*) FROM waste_companies")->fetchColumn();
$active = (int)$pdo->query("SELECT COUNT(*) FROM waste_companies WHERE is_active=1")->fetchColumn();
$direct = (int)$pdo->query("SELECT COUNT(*) FROM waste_companies WHERE is_active=0")->fetchColumn();
$member = (int)$pdo->query("SELECT COUNT(*) FROM waste_companies WHERE is_member=1")->fetchColumn();
$coop   = (int)$pdo->query("SELECT COUNT(*) FROM waste_companies WHERE is_coop=1")->fetchColumn();
$target = (int)$pdo->query("SELECT COUNT(*) FROM waste_companies WHERE is_active=1 AND is_coop=0")->fetchColumn();

echo "<h2>공제조합 데이터 적재</h2>";
echo "<p>적재 {$n}건.</p><ul>";
$exp = ['전체'=>[770,$total],'이용'=>[719,$active],'지점'=>[51,$direct],'회원'=>[358,$member],'조합원'=>[191,$coop],'타겟'=>[530,$target]];
foreach ($exp as $k=>$v) {
    $ok = $v[0]===$v[1] ? '✅' : '⚠️';
    echo "<li>{$ok} {$k}: 기대 {$v[0]} / 실제 {$v[1]}</li>";
}
echo "</ul>";
echo "<p>다음: <code>/cron_waste_geocode.php?key=econ-waste-geo</code> 반복 호출로 좌표화.</p>";
